def test_AC8_13_109_ai_ocr_gate_httpx_calls_use_absolute_api_urls() -> None:
    'AC8.13.109'; offenders: list[str] = []; relative_prefixes = ('/api/', '/assets/')
    def relative_url_prefix(node: ast.expr) -> str | None:
        if isinstance(node, ast.Constant) and isinstance(node.value, str): return node.value
        if isinstance(node, ast.JoinedStr) and node.values:
            first_value = node.values[0]
            if isinstance(first_value, ast.Constant) and isinstance(first_value.value, str): return first_value.value
        return None
    for relative_path in contract.gate_files():
        tree = ast.parse((ROOT / relative_path).read_text(encoding='utf-8'))
        for node in ast.walk(tree):
            if not isinstance(node, ast.Call): continue
            if not isinstance(node.func, ast.Attribute): continue
            if node.func.attr not in {'get', 'post', 'put', 'patch', 'delete'}: continue
            if not node.args: continue
            first_arg = node.args[0]; url_prefix = relative_url_prefix(first_arg); offenders.append(f'{relative_path}:{node.lineno} uses relative API URL {url_prefix!r}') if url_prefix and url_prefix.startswith(relative_prefixes) else None
    assert offenders == []
